fn is_integer(text: &Vec<char>) -> bool {
    // Check if all characters in the vector are digits
    text.iter().all(|&c| c.is_digit(10))
}

fn main() {
    // Example usage
    let digits = vec!['1', '2', '3', '4', '5'];
    let mixed = vec!['1', 'a', '3'];
    let empty: Vec<char> = vec![];

    println!("{}", is_integer(&digits)); // true
    println!("{}", is_integer(&mixed));  // false
    println!("{}", is_integer(&empty));  // true
}